import{_ as n,l as i,o as a,c as s,v as t,p as l,x as r,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"债务通缩","description":"","frontmatter":{"title":"债务通缩","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/debt-deflation.md","filePath":"econ/debt-deflation.md","lastUpdated":1789023840000}'),B={name:"econ/debt-deflation.md"};function c(h,e,A,m,_,f){const o=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="债务通缩" tabindex="-1">债务通缩 <a class="header-anchor" href="#债务通缩" aria-label="Permalink to &quot;债务通缩&quot;">​</a></h1><div class="epigraph"><p>价格水平下降提高名义债的实际负担；债务人是高支出倾向的一方时，通缩是再分配衰退，不是货币中性。</p><footer>—— Fisher, The Debt-Deflation Theory of Great Depressions, Econometrica 1933；Tobin 对再分配总需求</footer></div><p><a href="/econ/collateral-house-prices">上一课</a>的房价是资产价格。本课缺口是<strong>一般价格水平</strong>进入名义合同：Fisher 债务通缩。不重写 LTV 代数，不把 1933 写成思想史展览。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>货币中性：价格与名义债同比例，实际合同不变。合同若未指数化，通缩使财富从债务人转向债权人。Fisher：被迫出售、破产、货币流通下降，螺旋。Tobin：若债务人 MPC 更高，再分配降低总需求。缺口是把家庭债务与 KM/GK 的实际净值，接到名义刚性合同与菲利普斯——通缩不再只是 NK 的「需求不足的症状」，而是额外的放大。</p><p><span class="marginnote">Fisher, <em>Econometrica</em> 1933。Bernanke 对大萧条金融观点。Eggertsson–Krugman 下一课把同一再分配写成现代 ZLB 模型。Doepke and Schneider 的名义头寸谁持有。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>名义债 \\(B\\)，价格 \\(P\\)，实际负担 \\(B/P\\)。冲击：需求下降使 \\(P\\) 降（粘性未完全调整或预期通缩）。再分配进入 HANK 的 MPC 加权。抵押：实际房价 \\(q\\) 与 \\(B/P\\) 同时动。识别：未预期通胀对名义财富的效应（Auclert 的渠道）是债务通缩的一阶邻居。金本位、固定汇率是历史装置，放大通缩输入。</p>',8)),(a(),l(p,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%BB%B7%E6%A0%BC%E6%B0%B4%E5%B9%B3%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20REAL%5B%22%E5%AE%9E%E9%99%85%E5%80%BA%E5%8A%A1%E4%B8%8A%E5%8D%87%22%5D%0A%20%20REAL%20--%3E%20REDIST%5B%22%E5%80%BA%E6%9D%83%E4%BA%BA%20vs%20%E5%80%BA%E5%8A%A1%E4%BA%BA%22%5D%0A%20%20REDIST%20--%3E%20DEM%5B%22%E5%8A%A0%E6%80%BB%20MPC%20%E5%8A%A0%E6%9D%83%E9%9C%80%E6%B1%82%22%5D%0A%20%20DEM%20--%3E%20P%0A%20%20FIRE%5B%22%E7%81%AB%E7%BA%BF%E5%87%BA%E5%94%AE%22%5D%20--%3E%20Q%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20Q%20--%3E%20REAL%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与预期：若通缩被预见，事前利率会补偿；未预期才再分配。债务通缩理论强调合同签订后的价格意外。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是名义刚性合同加异质 MPC。完全指数化或一日内再谈判则通道关。银行：名义债的债务人若是银行，GK 净值被通缩打——日本与危机后的银行资本故事。主权：本币名义债被通胀稀释，外币债相反（后课原罪已在其它课，本单元后部主权再钉）。</p><p>政策：避免通缩的名义锚（上一单元锚定）有金融稳定价值，不只是菲利普斯。</p><p><span class="marginnote">大萧条经验是 Bernanke 与 Eichengreen 的领地。本课要机制，不重写全部年表——危机史后课再给模式。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不主张永远通胀稀释债务。未预期通胀有其它成本（菜单、不公、解钉）。下一课把借款人约束与 ZLB 写成现代解析模型。不交易 CPI 期货。</p><p>后课默认：通缩经名义债再分配放大衰退，当债务人 MPC 更高或受约束。下一课：Eggertsson–Krugman 的去杠杆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Fisher：通缩提高名义债实际负担，强迫去杠杆与需求下降。</li><li>关键是未预期价格与 MPC/约束不对称。</li><li>名义锚因此有金融稳定含义。</li><li>出处：Fisher, <em>Econometrica</em> 1933。</li></ul>',10))])}const D=n(B,[["render",c]]);export{P as __pageData,D as default};
